#### Phase 2: Event Data Service (Week 3-5)

**Step 2.1: Event Consumer Service (Kafka → Timestream)**

```python
import json, boto3
from kafka import KafkaConsumer

class EventConsumerService:
    def __init__(self, kafka_servers, db_name, table_name):
        self.consumer = KafkaConsumer(
            'claims.submitted', 'member.enrolled',
            bootstrap_servers=kafka_servers,
            security_protocol='SASL_SSL',
            sasl_mechanism='AWS_MSK_IAM',
            value_deserializer=lambda m: json.loads(m.decode('utf-8')),
            group_id='customer-access-consumer'
        )
        self.timestream = boto3.client('timestream-write')
        self.db = db_name
        self.table = table_name

    def write_to_timestream(self, event):
        customer_id = event.get('customer_id') or f"{event['member']['state']}-MEDICAID"
        record = {
            'Time': str(int(event['timestamp'] * 1000)),
            'TimeUnit': 'MILLISECONDS',
            'Dimensions': [
                {'Name': 'customer_id', 'Value': customer_id},
                {'Name': 'event_type', 'Value': event['event_type']},
                {'Name': 'event_id', 'Value': event['event_id']}
            ],
            'MeasureName': 'event_data',
            'MeasureValue': json.dumps(event),
            'MeasureValueType': 'VARCHAR'
        }
        self.timestream.write_records(DatabaseName=self.db, TableName=self.table, Records=[record])
```

**Step 2.2: Query Handler (REST API with Row-Level Security)**

```python
from flask import Flask, request, jsonify
import boto3, jwt

app = Flask(__name__)
timestream = boto3.client('timestream-query')

@app.route('/events/query', methods=['GET'])
def query_events():
    token = request.headers.get('Authorization', '').replace('Bearer ', '')
    payload = jwt.decode(token, options={"verify_signature": False})
    customer_id = payload.get('custom:customer_id')

    event_type = request.args.get('event_type')
    start_time = request.args.get('start_time', '2024-01-01T00:00:00Z')
    end_time = request.args.get('end_time')
    limit = min(int(request.args.get('limit', 100)), 1000)

    # ROW-LEVEL SECURITY: customer_id filter enforced server-side
    query = f"""
        SELECT time, event_id, event_type, measure_value::varchar AS event_data
        FROM "{DATABASE_NAME}"."{TABLE_NAME}"
        WHERE customer_id = '{customer_id}'
          AND time BETWEEN from_iso8601_timestamp('{start_time}') AND from_iso8601_timestamp('{end_time}')
    """
    if event_type:
        query += f" AND event_type = '{event_type}'"
    query += f" ORDER BY time DESC LIMIT {limit}"

    result = timestream.query(QueryString=query)
    events = [parse_row(row, result['ColumnInfo']) for row in result['Rows']]

    return jsonify({'events': events, 'count': len(events), 'customer_id': customer_id})
```

**Step 2.3: Webhook Notifier (Node.js)**

```javascript
const axios = require('axios');
const crypto = require('crypto');

class WebhookNotifier {
  generateSignature(payload, secret) {
    return crypto.createHmac('sha256', secret).update(JSON.stringify(payload)).digest('hex');
  }

  async sendWebhook(webhook, event, attempt = 1) {
    const payload = {
      webhook_id: webhook.webhook_id,
      event_id: event.event_id,
      event_type: event.event_type,
      data: event
    };
    const signature = this.generateSignature(payload, webhook.signing_secret);

    try {
      await axios.post(webhook.endpoint_url, payload, {
        headers: {
          'X-Webhook-Signature': `sha256=${signature}`,
          'X-Webhook-Id': webhook.webhook_id
        },
        timeout: 5000
      });
      console.log(`Webhook delivered: ${webhook.webhook_id}`);
    } catch (error) {
      if (attempt < 3) {
        const delay = Math.pow(2, attempt) * 60;
        await this.queueRetry(webhook, event, attempt + 1, delay);
      }
    }
  }
}
